import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import { describeErrorCode } from "../describe-error.js";
import { isRecord } from "../is-record.js";
import { HOSTED_ADMISSION_PATH, HOSTED_DELIVERY_HEADER, HOSTED_EXECUTION_PATH, } from "../hosted-delivery-protocol.js";
// A hosted v2 guest mounts no session HTTP (the control plane owns session
// reads), so these tests observe sessions through the persisted session
// store: `<stateRoot>/sessions/<sessionId>/{session.json,events.ndjson}`.
// The hosted execution route drains session durability before responding,
// so the files are complete once the POST returns.
export async function persistedSessionIds(stateRoot) {
    try {
        return (await readdir(join(stateRoot, "sessions"))).sort();
    }
    catch (error) {
        if (describeErrorCode(error) === "ENOENT") {
            return [];
        }
        throw error;
    }
}
export async function persistedSessionRecord(stateRoot, sessionId) {
    const raw = await readFile(join(stateRoot, "sessions", sessionId, "session.json"), "utf8");
    const record = JSON.parse(raw);
    if (!isRecord(record) ||
        typeof record.sessionId !== "string" ||
        typeof record.turnCount !== "number") {
        throw new Error(`session.json for ${sessionId} has no sessionId and turnCount`);
    }
    return { sessionId: record.sessionId, turnCount: record.turnCount };
}
export function persistedSessionEvents(stateRoot, sessionId) {
    return readFile(join(stateRoot, "sessions", sessionId, "events.ndjson"), "utf8");
}
export const HOSTED_JSON_HEADERS = {
    "content-type": "application/json",
    [HOSTED_DELIVERY_HEADER]: "1",
};
export function postHosted(url, body) {
    return fetch(url, {
        method: "POST",
        headers: HOSTED_JSON_HEADERS,
        body: JSON.stringify(body),
    });
}
export async function untilTerminal(first, poll) {
    const peeked = outcomeOf(await first.clone().json());
    if (peeked !== "started" && peeked !== "running") {
        return first;
    }
    for (;;) {
        const status = await poll();
        if (outcomeOf(await status.clone().json()) !== "running") {
            return status;
        }
        await new Promise((resolve) => setTimeout(resolve, 0));
    }
}
export function admitHosted(baseUrl, body) {
    return postHosted(`${baseUrl}${HOSTED_ADMISSION_PATH}`, {
        ...body,
        v: 2,
        mode: "start",
    }).then((start) => untilTerminal(start, () => postHosted(`${baseUrl}${HOSTED_ADMISSION_PATH}`, {
        v: 2,
        mode: "status",
        deliveryId: body.deliveryId,
    })));
}
export function executeHosted(baseUrl, input) {
    const envelope = {
        v: 2,
        admissionToken: input.admissionToken,
        sessionPublicId: input.sessionPublicId,
    };
    return postHosted(`${baseUrl}${HOSTED_EXECUTION_PATH}`, {
        ...envelope,
        mode: "start",
    }).then((start) => untilTerminal(start, () => postHosted(`${baseUrl}${HOSTED_EXECUTION_PATH}`, {
        ...envelope,
        mode: "status",
    })));
}
function outcomeOf(body) {
    return isRecord(body) ? body.outcome : undefined;
}
